parameters.jsCode:
const mainStyle = $('Split Out').all()[0].json.main_style_prompt;
const enrichedTracks = $('Enrich Track Package').all();

return $input.all().map((item, index) => {
  const track = enrichedTracks[index].json;
  const addendum = item.json.output?.[0]?.content?.[0]?.text || item.json.style_addendum || "";

  return {
    json: {
      title: track.track_title,
      lyrics: track.lyrics,
      style: `${mainStyle}\n\n${addendum}`,
      customMode: true,
      instrumental: false
    }
  };
});;

const items = $input.all();
const albumTitle = $('Get Album Data').all()[0].json.album_title;
let doc = `# One-Tool Album Factory - Suno Manual Upload Package\n\n`;

for (const item of items) {
  const song = item.json.song;

  doc += `---\n\n`;
  doc += `# ${song.title}\n\n`;
  doc += `## Style\n\n${song.style}\n\n`;
  doc += `## Lyrics\n\n${song.lyrics}\n\n`;
}

return [
  {
    json: {
      fileName: `${albumTitle.replace(/\s+/g,'_')}_Suno_Package.md`,
      content: doc
    }
  }
];

const items = $input.all();
const albumTitle = $('Get Album Data').all()[0].json.album_title;

let html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>Album Package || ${albumTitle}</title>
<style>
body { font-family: Arial, sans-serif; line-height: 1.6; padding: 40px; }
h1 { border-bottom: 2px solid #333; }
pre { white-space: pre-wrap; background: #f4f4f4; padding: 15px; }
.track { margin-bottom: 60px; }
</style>
</head>
<body>
<h1>One-Tool Album Factory | ${albumTitle}</h1>
`;

for (const item of items) {
  const song = item.json.song;

  html += `  
<div class="track">
<h2>${song.title}</h2>
<h3>Style</h3>
<pre>${song.style}</pre>
<h3>Lyrics</h3>
<pre>${song.lyrics}</pre>
</div>
`;
}

html += `</body></html>`;

return [
  {
    json: {
      fileName: "album_package_"+albumTitle+".html"
    },
    binary: {
      data: {
        data: Buffer.from(html, "utf8").toString("base64"),
        mimeType: "text/html",
        fileName: "album_package_"+albumTitle+".html"
      }
    }
  }
];
